package auction

import (
    "context"
    "time"
)

type BidCollector struct {
    timeout time.Duration
}

func (bc *BidCollector) CollectBids(ctx context.Context, dsps []string) []Bid {
    ctx, cancel := context.WithTimeout(ctx, 10*time.Millisecond)
    defer cancel()

    // Asynchronous fanout with strict 10ms hard deadline
    ch := make(chan Bid, len(dsps))
    for _, dsp := range dsps {
        go func(endpoint string) {
            bid := callDsp(ctx, endpoint)
            ch <- bid
        }(dsp)
    }
    return gatherUntilDeadline(ctx, ch)
}
